const hic=(n,s)=>`<svg class="hi" viewBox="0 0 24 24" aria-hidden="true"${s?` style="width:${s}px;height:${s}px"`:''}>${HI[n]||''}</svg>`;
const CHI={so:'social',we:'web',em:'mail',sg:'screen'};
Object.assign(S,{ev:null,evSub:'list',evId:null,evYear:null,evF:{so:'',we:'',em:'',sg:''},socSub:localStorage.pulseSocSub||'posts',cov:{k:'sev',dir:-1,br:''},evItemF:'all',evItemN:12});
