const hk=n=>n>=1e6?(n/1e6).toFixed(n>=1e7?0:1)+'M':n>=1e4?Math.round(n/1e3)+'K':n>=1e3?(n/1e3).toFixed(1)+'K':nf(n);
const hd=(k,o)=>k?P.fmtDate(k,o):'';
const hT=v=>{let t=Date.parse(v);if(!isNaN(t))return t;const m=String(v||'').match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})\s*(AM|PM)?/i);if(!m)return NaN;let h=+m[4]%12;if(/pm/i.test(m[6]||''))h+=12;else if(!m[6])h=+m[4];return Date.UTC(+m[1],+m[2]-1,+m[3],h-9,+m[5])};
const hTime=v=>{const t=hT(v);return isNaN(t)?String(v||''):fdtJ(t)+' JST'};
const mY=k=>new Date(k+'T00:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',month:'short',year:'numeric'});
const hrng=(a,b)=>!a?'':a===b?hd(a,{weekday:'short'}):a.slice(0,7)===b.slice(0,7)?`${hd(a,{weekday:'short'})}–${+b.slice(8)}`:`${hd(a)} – ${hd(b)}`;
