const evPass=(ch,key)=>{const f=S.evF[ch];if(!f)return true;const l=evOf(key);return f==='none'?!l.length:l.some(x=>x.ev===f)};
function bindEvFilter(after){$$('[data-evf] [data-evv]').forEach(b=>b.onclick=()=>{const ch=b.closest('[data-evf]').dataset.evf;S.evF[ch]=b.dataset.evv;if(after)after(ch);else render()})}
// ---------- shared bits ----------
function spark(arr,color,h){h=h||42;const w=200;if(!arr||arr.length<2)return `<svg class="sp" viewBox="0 0 ${w} ${h}"></svg>`;const mx=Math.max(...arr),mn=Math.min(...arr);const pts=arr.map((v,i)=>[i/(arr.length-1)*w,h-4-(v-mn)/(mx-mn||1)*(h-10)]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');const id='g'+color.slice(1);
 return `<svg class="sp" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".35"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="${d} L${w} ${h} L0 ${h} Z" fill="url(#${id})"/><path d="${d}" fill="none" stroke="${color}" stroke-width="1.8" vector-effect="non-scaling-stroke"/></svg>`}
const dayArr=(s,e,fn)=>{const a=[];for(let k=s;k<=e;k=P.addDays(k,1))a.push(fn(k));return a};
const dots=c=>`<span class="dots" title="Social · Web · Email · Signage">${HCH.map(k=>`<i class="${k} ${c[k]?'f':''}"></i>`).join('')}</span>`;
const chCov=R=>({so:R&&R.so.n>0,we:R&&R.we.pages.length>0,em:R&&R.em.camps.length>0,sg:R&&R.sg.slides.length>0});
