 const bestSo=R.so.list.slice().sort((a,b)=>b.v-a.v)[0],reels=R.so.list.filter(r=>/reel|video/i.test(r.type)),photos=R.so.list.filter(r=>/photo|image|carousel/i.test(r.type));
