function hubSgDays(R){if(!R.sg.slides.length)return '—';const log=sgLog(),n=new Set();for(const [d,names] of Object.entries(log))if(d>=R.ws&&d<=R.we_&&R.sg.slides.some(s=>names.includes(s)))n.add(d);return n.size||1}
function hubEvChart(e,R){const W=1000,H=250,pad=52;const ks=[];for(let k=R.ws;k<=R.we_;k=P.addDays(k,1))ks.push(k);const n=ks.length;const val=k=>R.daily.get(k)||{so:0,we:0,em:0};
 const tot=ks.map(k=>{const v=val(k);return v.so+v.we+v.em});const raw=Math.max(1,...tot),m0=Math.pow(10,Math.floor(Math.log10(raw/4))),step=[1,2,2.5,5,10].map(x=>x*m0).find(x=>raw/x<=5)||10*m0,mx=Math.ceil(raw/step)*step;const bw=(W-pad)/n;let bars='',grid='';
 ks.forEach((k,i)=>{let y=H-24;const x=pad+i*bw+1;const v=val(k);[[v.em,HC.em],[v.we,HC.we],[v.so,HC.so]].forEach(([q,c])=>{if(!q)return;const h=q/mx*(H-40);y-=h;bars+=`<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${Math.max(1,bw-2).toFixed(1)}" height="${h.toFixed(1)}" fill="${c}" opacity=".85" rx="1.5"><title>${hd(k)}: ${nf(q)}</title></rect>`})});
 for(let g=0;g<=mx;g+=step){const y=H-24-g/mx*(H-40);grid+=`<line x1="${pad}" x2="${W}" y1="${y}" y2="${y}" stroke="rgba(255,255,255,.08)"/><text x="${pad-6}" y="${y+4}" text-anchor="end" font-size="11" fill="rgba(238,241,246,.6)">${hk(g)}</text>`}
 const ex=pad+ks.indexOf(e.s)*bw,ew=(P.daysBetween(e.s,e.e))*bw;const lab=ks.map((k,i)=>[k,i]).filter(([k,i])=>i%Math.max(1,Math.round(n/6))===0).map(([k,i])=>`<text x="${pad+i*bw+bw/2}" y="${H-6}" font-size="11" fill="rgba(238,241,246,.6)" text-anchor="middle">${hd(k)}</text>`).join('');
 const t=ks.indexOf(P.todayKey());const now=t>=0?`<line x1="${pad+t*bw+bw/2}" x2="${pad+t*bw+bw/2}" y1="6" y2="${H-24}" stroke="var(--glow)" stroke-dasharray="2 4"/><text x="${pad+t*bw+bw/2+4}" y="${H-30}" font-size="11" fill="var(--glow)">today</text>`:'';
 const log=sgLog(),lanes=R.sg.slides.slice(0,4).map((s,j)=>{const seen=ks.filter(k=>(log[k]||[]).includes(s));const a=seen.length?ks.indexOf(seen[0]):Math.max(0,t),b=seen.length?ks.indexOf(seen[seen.length-1]):Math.max(0,t);const y=8+j*24;
  return `<text x="${pad-6}" y="${y+11}" text-anchor="end" font-size="11" fill="rgba(238,241,246,.6)">Slide ${j+1}</text><rect x="${pad+a*bw}" y="${y}" width="${Math.max(bw,(b-a+1)*bw)}" height="14" rx="7" fill="${HC.sg}" opacity=".75"><title>${esc(sgName(s))}</title></rect><text x="${pad+a*bw+8}" y="${y+11}" font-size="11" fill="#0e1420">${esc(sgName(s).slice(0,40))}${seen.length?` · seen ${hd(seen[0])}${seen.length>1?'–'+hd(seen[seen.length-1]):''}`:''}</text>`}).join('');
 return `<svg class="hchart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily touchpoints">${grid}<rect x="${ex}" y="10" width="${Math.max(bw,ew)}" height="${H-34}" fill="rgba(255,255,255,.07)"/>${bars}<line x1="${ex}" x2="${ex}" y1="6" y2="${H-24}" stroke="#eef1f6" stroke-dasharray="3 3"/><text x="${ex+Math.max(bw,ew)+6}" y="20" font-size="12" fill="#eef1f6">Event</text>${now}${lab}</svg>${R.sg.slides.length?`<svg class="hchart" viewBox="0 0 ${W} ${8+Math.min(4,R.sg.slides.length)*24}">${lanes}</svg>`:''}`}
function bindEvent(){$$('[data-itf]').forEach(b=>b.onclick=()=>{S.evItemF=b.dataset.itf;S.evItemN=12;render()});const m=$('#itMore');if(m)m.onclick=()=>{S.evItemN=1e4;render()};
 const sh=$('#evShare');if(sh)sh.onclick=()=>window.PulseShare&&PulseShare.open(S.evShare)}
// review queue: decisions are kept on this device and exported as rows for the sheet's Links tab
function hubReview(){const M=evM(),dec=EVD.get();const evs=evList().filter(e=>e.s);
 const q=M.review.map(r=>{const i=itemInfo(r.key,evGet(r.best.ev));if(!i)return '';const e=evGet(r.best.ev);const col=r.best.score>=80?'var(--glow)':r.best.score>=60?'var(--warn)':'var(--bad)';
  const others=[...new Set([...r.alts.map(a=>a.ev),...evs.filter(x=>x.id!==e.id&&i.d&&P.evWindow(x).ws<=i.d&&P.evWindow(x).we>=i.d).map(x=>x.id)])].filter(id=>id!==e.id).map(evGet).filter(Boolean);
  return `<div class="qi" data-key="${esc(r.key)}"><div class="th t-${i.ch}">${i.th?`<img data-th="${esc(i.th)}" alt="">`:hic(CHI[i.ch],18)}</div><div class="ib"><div class="t">${esc(i.t)}</div><div class="s"><span class="cb ${i.ch}">${HN[i.ch]}</span>${esc(i.s)}<span class="why">${esc(r.best.why)}</span>${i.v?`<span>${i.v} ${i.u}</span>`:''}</div>
   <div class="sug"><span class="to">→ <b>${esc(e.name)}</b></span><span class="conf"><span class="cbar"><span style="width:${r.best.score}%;background:${col}"></span></span>${r.best.score}% match</span>${r.alts.length?`<span class="mut sm">also: ${r.alts.map(a=>esc(evShort(evGet(a.ev)||{name:a.ev}))+' '+a.score+'%').join(', ')}</span>`:''}
   <div class="acts"><button class="ok" data-dec="link" data-ev="${esc(e.id)}">${hic('check',13)} Link</button><button class="no" data-dec="no" data-ev="${esc(e.id)}">Not this</button>${others.length?`<label class="other"><select data-dec="other" aria-label="Link to another event"><option value="">Other event…</option>${others.map(o=>`<option value="${esc(o.id)}">${esc(o.name)} (${hd(o.s)})</option>`).join('')}</select></label>`:''}</div></div></div></div>`}).join('');
 return `<button class="hback" data-nav="events">${hic('back',15)}Strategic events</button><div class="hph"><div><h1>Review matches</h1><p>Pulse links what it is sure about. These might belong to an event: confirm once and your answer sticks on this device; copy them into the sheet’s Links tab to keep them for everyone.</p></div></div>
 <div class="sgrid"><div class="card rq"><h2>Waiting <small>${M.review.length} to review · ${[...M.byEvent.values()].reduce((a,l)=>a+l.length,0)} linked automatically</small></h2>${q||'<p class="mut">Nothing waiting. Every likely match is linked or answered.</p>'}
  <div class="pnote"><b>How sure is sure?</b> 90% and up links by itself (block it in the Links tab if it is wrong). 50–89% waits here. Your answers here are saved on this device until they are in the sheet.</div></div>
 <div class="hside"><div class="card"><h2>Your answers <small>${dec.length} on this device</small></h2>${dec.length?`<div class="declist">${dec.slice().reverse().slice(0,12).map(x=>{const i=itemInfo(x.key,evGet(x.ev)),e=evGet(x.ev);return `<div class="dec"><span class="${x.act==='link'?'up':'mut'}">${x.act==='link'?'Link':'Not this'}</span><span>${esc(i?i.t:x.key)} <small>→ ${esc(e?e.name:x.ev)}</small></span><button data-undo="${esc(x.key+'|'+x.ev)}" aria-label="Undo">Undo</button></div>`}).join('')}</div>
   <p class="mut sm">Paste these rows into the Links tab (columns Event ID, Channel, Item, Action, Notes). Once the next publish includes them, you can clear them here.</p><div class="acts"><button class="hbtn" id="decCopy">${hic('copy',15)}Copy ${dec.length} row${dec.length===1?'':'s'} for the Links tab</button><button class="hbtn ghost" id="decCsv">Download CSV</button><button class="hbtn ghost" id="decClear">Clear</button></div>`:'<p class="mut sm">Answers you give here show up as rows to paste into the sheet’s Links tab.</p>'}</div>
  <div class="card"><h2>Matching rules <small>applied in this order</small></h2><ol class="rulelist"><li><b>Inside the campaign window</b> (promo start → after). Anything outside is never matched.</li><li><b>Exact signals</b>: a listed hashtag (97%), a listed web page or a post linking to it (96%).</li><li><b>The event’s name or other names</b> in post text, page address, newsletter story or slide name: 86–97%, lower for short or common words.</li><li><b>Every word, any order</b> (or a close spelling): 58–72%, always reviewed.</li><li><b>Two events fit?</b> The higher score is suggested; both show here.</li><li><b>Links tab</b> (Link / Not this) always wins.</li></ol></div></div></div>`}
const decRows=()=>EVD.get().map(x=>{const i=itemInfo(x.key,evGet(x.ev));return [x.ev,HN[x.key.slice(0,2)],i?i.sheet:x.key.slice(3),x.act==='link'?'Link':'Not this',`From Pulse review ${String(x.at||'').slice(0,10)}${i?': '+i.t:''}`]});
function bindReview(){$$('.qi [data-dec]').forEach(b=>{const go=(act,ev)=>{const key=b.closest('.qi').dataset.key;const a=EVD.get().filter(x=>!(x.key===key&&x.ev===ev));a.push({key,ev,act,at:new Date().toISOString()});EVD.set(a)};
  if(b.tagName==='SELECT')b.onchange=()=>{if(!b.value)return;const sug=b.closest('.qi').querySelector('[data-dec=no]').dataset.ev;go('no',sug);go('link',b.value);toast('Linked to '+evShort(evGet(b.value)));render()};
  else b.onclick=()=>{go(b.dataset.dec,b.dataset.ev);toast(b.dataset.dec==='link'?'Linked':'Won’t suggest that again');render()}});
 $$('[data-undo]').forEach(b=>b.onclick=()=>{const [k,ev]=b.dataset.undo.split('|');EVD.set(EVD.get().filter(x=>!(x.key===k&&x.ev===ev)));render()});
 const c=$('#decCopy');if(c)c.onclick=async()=>{const t=decRows().map(r=>r.map(v=>String(v).replace(/[\t\n]/g,' ')).join('\t')).join('\n');try{await navigator.clipboard.writeText(t);toast('Copied. Paste into the Links tab, first empty row')}catch(e){openSheet(`<h3>Rows for the Links tab</h3><textarea class="decta" readonly>${esc(t)}</textarea>`)}};
 const v=$('#decCsv');if(v)v.onclick=()=>{const q=s=>/[",\n]/.test(s)?'"'+String(s).replace(/"/g,'""')+'"':String(s);const t=[['Event ID','Channel','Item','Action','Notes'],...decRows()].map(r=>r.map(q).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download=`pulse-links-${P.todayKey()}.csv`;a.click()};
 const cl=$('#decClear');if(cl)cl.onclick=()=>{if(confirm('Clear your answers on this device? Copy them into the sheet first if you want to keep them.')){EVD.set([]);render()}}}
// ---------- signage: a small on-device log of what was in rotation each day (ScreenCloud publishes only "now") ----------
function sgLog(){try{return JSON.parse(localStorage.pulseSgLog||'{}')}catch(e){return {}}}
function sgLogNow(){const d=SG.data;if(!d||!d.items)return;const k=P.jstKey(new Date(d.checked||Date.now()).getTime()),L=sgLog();L[k]=[...new Set(d.items.map(i=>i.name))];const ks=Object.keys(L).sort();while(ks.length>120)delete L[ks.shift()];try{localStorage.pulseSgLog=JSON.stringify(L)}catch(e){}}
// signage tab: event chips on slides + filter by event
function hubAfterSignage(){const d=SG.data;if(!d||!evM())return;sgLogNow();const keys=d.items.map(i=>'sg:'+i.name);const play=$('.sgplay');if(!play)return;
 const f=document.createElement('div');f.innerHTML=hubEvFilter('sg',keys);play.querySelector('h2').after(f.firstElementChild);
 $$('.sgth').forEach(el=>{const k='sg:'+el.title;const l=evOf(k);if(l.length){const e=evGet(l[0].ev);if(e){const b=document.createElement('button');b.className='sgev';b.dataset.nav='event:'+e.id;b.textContent=evShort(e);el.appendChild(b)}}el.hidden=!evPass('sg',k)});
 bindEvFilter(()=>render())}
