{const i=SOURCES.findIndex(s=>s.k==='events');const src={k:'events',l:'Strategic Events (Google Sheet)',short:'Events',due:8,get:evSrc,empty:()=>!localStorage.pulsePass?'Unlock Pulse with your passcode to load events.':'Not published yet. It arrives with the next encrypted publish.'};if(i>=0)SOURCES[i]=src;else SOURCES.push(src)}
{const at=SET_GROUPS.findIndex(g=>g.id==='data');SET_GROUPS.splice(at+1,0,{id:'events',sec:3,title:'Events & programs',icon:SI('list'),val:()=>{const d=evData();return d?`${d.events.length} events`:'Not loaded'},
 page:()=>{const d=evData(),M=evM(),dec=EVD.get();return `<div class="sgt">Strategic events</div><div class="slist">${d?`<div class="srow"><span class="sic">${SI('list')}</span><span class="slb">${nf(d.events.length)} events · ${nf(d.events.filter(e=>e.s).length)} dated<small>From the MCCS Pulse Strategic Events sheet${d.updated?', published '+hTime(d.updated):''}</small></span></div>
   <button class="srow" id="spEvGo"><span class="sic">${SI('chev')}</span><span class="slb">Open Strategic events<small>${M?M.review.length+' matches waiting for review':''}</small></span>${SI('chev','schev')}</button>${d.sheet&&d.sheet.url?`<a class="srow" href="${esc(d.sheet.url)}" target="_blank" rel="noopener"><span class="sic">${SI('doc')}</span><span class="slb">Edit the sheet<small>Events, Links and Programs tabs</small></span>${SI('out','schev sout')}<span class="sr">(opens in a new tab)</span></a>`:''}`:`<div class="srow"><span class="sic">${SI('list')}</span><span class="slb">Not loaded yet<small>Arrives with the next encrypted publish</small></span></div>`}</div>
   <p class="sfoot">Campaign window: 30 days before to 7 days after each event unless Promo start / Promo end are set in the sheet. 90% and up links by itself; 50–89% waits in Review matches; the Links tab always wins.</p>
   <div class="sgt">Your review answers</div><div class="slist"><div class="srow"><span class="sic">${SI('check')}</span><span class="slb">${dec.length} answer${dec.length===1?'':'s'} on this device<small>Copy them into the Links tab from Review matches</small></span>${dec.length?'<button class="sact" id="spDecGo">Review</button>':''}</div></div>
   <div class="sgt">Program weak spots: quiet after</div><div class="slist noic" role="radiogroup" aria-label="Quiet after">${[30,45,60,90].map(n=>radioRow('wd',n,CFG.weakDays===n,n+' days',n===45?'Default':'')).join('')}</div><p class="sfoot">A program with no posts (own page or mentions) for this long is flagged on Programs and in Today’s Needs attention. Seasonal festival programs are flagged only when their event is near.</p>`},
 bind:()=>{spRadios('[data-wd]','wd',v=>{CFG.weakDays=+v;COVC.key=''});const g=$('#spEvGo');if(g)g.onclick=()=>{closeSettings(false);hubNav('events')};const r=$('#spDecGo');if(r)r.onclick=()=>{closeSettings(false);hubNav('review')}}})}
